#
# simple quick-start config script with dbtext
#

# ----------- global configuration parameters ------------------------

#debug\_mode=yes
udp\_workers=4

check\_via=no    # (cmd. line: -v)
dns=no          # (cmd. line: -r)
rev\_dns=no      # (cmd. line: -R)

